contracts/BoostVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title BoostVerifier — gas money drawn on an identity's own treasury
 *
 * A device at zero cannot act. Every exit from {IdentityContract}'s treasury is
 * `onlyRivet` on `msg.sender`, so a flat rivet cannot reach the identity's own
 * money however much of it is sitting there, and no contract can pay the gas
 * for a transaction it did not send. That is the corner this closes.
 *
 * A **Boost** is a statement signed by a rivet while it still has funds, naming
 * a device of the same identity and a ceiling. It costs nothing to issue and
 * consumes no nonce, so a device can leave itself a reserve. Later, anyone may
 * present it here: this contract checks it, pays the named device out of the
 * treasury, and reimburses the presenter's gas in the same transaction. The
 * carrier fronts gas for one block and is made whole; nothing is given away,
 * because the money is the identity's own, released by its own rivet.
 *
 * **No upgrade is needed.** A rivet does not have to be a key — it can be code.
 * Membership is a fact the identity contract holds about an address, and the
 * mint path already relies on that when the factory holds authority for the
 * length of one transaction. So one deployment of this contract, added as a
 * rivet by one ordinary transaction, gives Boosts to identities that are
 * already deployed and cannot be changed.
 *
 * **What adopting it costs.** Rivet membership is total authority: once added,
 * this contract could also add members, remove them, and move the whole
 * treasury. It is written to be small enough to read in one sitting and has no
 * administrator, no owner, and nothing that can be pointed at new code later.
 * Withdrawal is `removeRivet(address(this))` and takes effect immediately,
 * which is a better position than an upgradeable contract would leave.
 *
 * The signed bytes are defined once, in `client/boost-message.mjs`, and every
 * issuer imports that module. `digest()` below is the same construction in
 * Solidity and the test asserts the two agree.
 */

interface IIdentity {
    function isValidSignature(bytes32 hash, bytes memory signature) external view returns (bytes4);
    function isAuthorized(address rivet) external view returns (bool);
    function rivetActive(address rivet) external view returns (bool);
    function sendETH(address payable recipient, uint256 amount) external;
    function getBalance() external view returns (uint256);
}

contract BoostVerifier {

    bytes32 public constant BOOST_TYPEHASH = keccak256(
        "EpisteryBoost(address verifier,address identity,uint256 chainId,address recipient,uint256 capWei,uint256 writes,uint256 notAfter,uint256 boostId,uint256 epoch)"
    );

    /// ERC-1271's "this signature is valid" answer.
    bytes4 private constant EIP1271_MAGIC = 0x1626ba7e;

    /// Gas one ordinary identity write costs. Matches the relay's `setMember`
    /// budget, which is the dearest of the everyday writes, so a Boost sized in
    /// writes errs high rather than short. Public so anyone can check the
    /// arithmetic rather than trust it.
    uint256 public constant GAS_PER_WRITE = 250_000;

    /// Multiple of the current base fee a Boost funds to, so a device that is
    /// topped up can still act when the next block is dearer than this one.
    uint256 public constant FEE_HEADROOM = 2;

    /// Gas this call spends outside the metered span — the two payouts, the
    /// final accounting, and the transaction's own 21k. Deliberately a rough
    /// over-estimate: a carrier that is under-reimbursed will not carry.
    uint256 public constant PRESENT_OVERHEAD = 90_000;

    /**
     * The signed statement. Passed as a calldata struct rather than as loose
     * arguments because the checks plus the accounting overflow the EVM's stack
     * otherwise, and because a caller assembling seven positional numbers in
     * the right order is a bug waiting to be written.
     */
    struct Boost {
        address identity;            // the IdentityContract it is drawn on
        address payable recipient;   // the device to be paid
        uint256 capWei;              // total this Boost may cost the treasury
        uint256 writes;              // ordinary writes it should cover
        uint256 notAfter;            // unix seconds; required, never 0
        uint256 boostId;             // presentable once
        uint256 series;              // the series it belongs to
    }

    /// identity => the series outstanding Boosts must belong to.
    mapping(address => uint256) public epoch;

    /// identity => boostId => already presented.
    mapping(address => mapping(uint256 => bool)) public spent;

    event BoostPresented(
        address indexed identity,
        address indexed recipient,
        uint256 boostId,
        uint256 paid,
        uint256 reimbursed,
        address carrier
    );

    event SeriesAdvanced(address indexed identity, uint256 epoch, address by);

    /**
     * @notice The 32 bytes an issuer signs. Mirror of client/boost-message.mjs.
     * @dev `address(this)` is in the digest as the EIP-712 domain separator's
     * verifying contract. Without it an identity that had adopted two verifiers
     * could have one Boost presented at each, since each keeps its own spent
     * map, and the ceiling would be paid twice.
     */
    function digest(
        address identity,
        address recipient,
        uint256 capWei,
        uint256 writes,
        uint256 notAfter,
        uint256 boostId,
        uint256 series
    ) public view returns (bytes32) {
        return keccak256(abi.encode(
            BOOST_TYPEHASH,
            address(this),
            identity,
            block.chainid,
            recipient,
            capWei,
            writes,
            notAfter,
            boostId,
            series
        ));
    }

    /**
     * @notice Present a Boost. Callable by anyone holding one.
     *
     * Four checks carry the safety, and each is evaluated NOW rather than when
     * the Boost was issued, which is what makes revocation free:
     *
     * 1. the device being paid is an active rivet of this identity, so a Boost
     *    is a gas instrument for an identity's own devices and retiring a lost
     *    device voids every Boost aimed at it;
     * 2. the issuer is an active rivet, so removing a compromised device voids
     *    everything it ever issued, retroactively;
     * 3. the id is unspent and the series is current, so one Boost pays once
     *    and advancing the series voids the whole reserve at one stroke;
     * 4. the reimbursement is measured and the ceiling bounds the pair, so
     *    presenting is break-even and never a way to drain a treasury.
     *
     * A carrier should simulate before presenting: an empty treasury means it
     * pays the gas and collects nothing.
     */
    function present(Boost calldata b, bytes calldata signature) external {
        uint256 gasStart = gasleft();
        IIdentity id = IIdentity(b.identity);

        // Fail closed and legibly, in the order that costs least to discover.
        require(b.notAfter != 0, "boost has no expiry");
        require(block.timestamp <= b.notAfter, "boost expired");
        require(b.capWei != 0, "boost has no ceiling");
        require(!spent[b.identity][b.boostId], "boost already presented");
        require(epoch[b.identity] == b.series, "boost series superseded");
        require(
            id.isAuthorized(address(this)) && id.rivetActive(address(this)),
            "this verifier is not a rivet of that identity"
        );
        require(
            id.isAuthorized(b.recipient) && id.rivetActive(b.recipient),
            "recipient is not an active rivet"
        );

        // The issuer check IS the identity contract's own ERC-1271: it recovers
        // the signer from the personal_sign wrapper and answers only for an
        // authorised, active rivet. Delegating it means no second copy of the
        // rivet rule and no ecrecover here to get wrong.
        require(
            id.isValidSignature(
                digest(b.identity, b.recipient, b.capWei, b.writes, b.notAfter, b.boostId, b.series),
                signature
            ) == EIP1271_MAGIC,
            "boost not issued by an active rivet"
        );

        spent[b.identity][b.boostId] = true;

        uint256 paid;
        uint256 reimbursed;
        {
            // The carrier is reimbursed for what it actually spent, at the price
            // it actually paid. The ceiling bounds the payout and the
            // reimbursement TOGETHER, so one Boost can never cost the treasury
            // more than its stated figure.
            reimbursed = (gasStart - gasleft() + PRESENT_OVERHEAD) * tx.gasprice;
            if (reimbursed > b.capWei) reimbursed = b.capWei;

            // Sized on presentation, not at issue. A fixed amount rots: one
            // written when fees were low is worthless in a busy market. The
            // ceiling is what the issuer fixed; the amount is what the chain
            // says that work costs now. A chain with no base fee (non-1559)
            // reports zero, where the only honest answer is the ceiling.
            uint256 fee = block.basefee;
            paid = fee == 0 ? b.capWei : b.writes * GAS_PER_WRITE * fee * FEE_HEADROOM;
            if (paid > b.capWei - reimbursed) paid = b.capWei - reimbursed;
        }

        require(id.getBalance() >= paid + reimbursed, "treasury cannot cover this boost");

        // `sendETH` forwards only the 2300-gas stipend, so both payees must be
        // ordinary accounts. A carrier with logic in its fallback cannot be
        // reimbursed, which is a documented condition of carrying rather than a
        // case to work around here.
        if (paid > 0) id.sendETH(b.recipient, paid);
        if (reimbursed > 0) id.sendETH(payable(msg.sender), reimbursed);

        emit BoostPresented(b.identity, b.recipient, b.boostId, paid, reimbursed, msg.sender);
    }

    /**
     * @notice Void every outstanding Boost of an identity at one stroke.
     *
     * Any active rivet may do this, because a reserve is the identity's own
     * paper and the hour it leaks is not the hour to look for a quorum. It is
     * an ordinary transaction, so it needs a solvent device — a flat one cannot
     * revoke, which is the accepted limit of this version.
     */
    function advanceSeries(address identity) external returns (uint256) {
        IIdentity id = IIdentity(identity);
        require(
            id.isAuthorized(msg.sender) && id.rivetActive(msg.sender),
            "only an active rivet may advance the series"
        );
        uint256 next = ++epoch[identity];
        emit SeriesAdvanced(identity, next, msg.sender);
        return next;
    }
}

contracts/EpisteryAccess.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title EpisteryAccess — common access + data mechanism for all epistery contracts
 *
 * The one ACL-and-data primitive shared by IdentityContract, DomainAgent, and
 * CampaignContract. A contract is organized into named **sections** — mini-folders,
 * one per plugin or per session. Each section carries, together:
 *
 *   - an **ACL** (who may touch it, by role), and
 *   - its **data**: public attributes (world-readable) and secret attributes
 *     (gated by the section's ACL). Public and secret are equal citizens.
 *
 * Authorization is on-chain and blind: a relay/plugin asks `roleOf(section, addr)`
 * (or `authorized(section, addr, minRole)`) and the chain answers — no off-chain
 * gatekeeper decides access. Bulk data still lives in Storj rooted at the contract;
 * a section holds the authoritative small stuff (membership, keys, config).
 *
 * Roles: 0 none · 1 read · 2 write · 3 admin · 4 owner.
 *
 * The base is agnostic about WHO the contract's base authorities are. A concrete
 * contract defines that by overriding `_isSteward` — e.g. any rivet of an identity,
 * or the owner/host of a domain, or the advertiser/agency of a campaign. Stewards
 * have implicit role 4 on every section; anyone else has exactly the role the
 * section's ACL grants them.
 */
abstract contract EpisteryAccess {

    // ── roles ──────────────────────────────────────────────────────────────
    uint8 constant ROLE_NONE  = 0;
    uint8 constant ROLE_READ  = 1;
    uint8 constant ROLE_WRITE = 2;
    uint8 constant ROLE_ADMIN = 3;
    uint8 constant ROLE_OWNER = 4;

    // The "default" ACL list — the role every address gets on a section unless
    // explicitly listed. It IS a normal ACL entry, keyed on this sentinel address
    // and set with the ordinary setMember(section, DEFAULT_MEMBER, role) (an admin
    // act); roleOf falls back to it. This makes the chain the ONE membership
    // system's answer for unlisted identities — a "public" session is just one
    // whose default grants READ. Mirrors epistery-host's "default" list / the
    // app's off-chain defaultRole, but on-chain so every authorizer reads the
    // same source. address(uint160(...)) casts a plain number → address, sidestepping
    // the address-literal checksum rule for a reserved, non-EOA sentinel.
    address public constant DEFAULT_MEMBER = address(uint160(0xDEFA0117));

    // ── ACL ────────────────────────────────────────────────────────────────
    struct ACLEntry { address addr; string name; uint8 role; string meta; }
    struct Membership { string section; uint8 role; }

    mapping(string => ACLEntry[]) private _acl;            // section => entries
    mapping(string => mapping(address => uint256)) private _aclIndex; // section => addr => index+1 (0 = absent)
    mapping(address => Membership[]) private _memberships; // addr => sections it's in

    string[] private _sectionNames;                        // every section ever created
    mapping(string => bool) private _sectionSeen;

    // ── attributes (the section's data) ────────────────────────────────────
    mapping(string => mapping(string => string)) private _public;  // section => key => public value
    mapping(string => mapping(string => bytes))  private _secret;   // section => key => secret value
    mapping(string => string[]) private _publicKeyList;             // section => public key names
    mapping(string => mapping(string => bool)) private _publicKeySeen;
    mapping(string => string[]) private _secretKeyList;
    mapping(string => mapping(string => bool)) private _secretKeySeen;

    // ── invites (join a section without a pre-known address) ────────────────
    struct Invite { string section; uint8 role; address issuer; bool used; }
    mapping(bytes32 => Invite) private _invites;           // codeHash => invite

    // ── events ─────────────────────────────────────────────────────────────
    event MemberSet(string section, address indexed addr, uint8 role, address indexed by);
    event MemberRemoved(string section, address indexed addr, address indexed by);
    event PublicSet(string section, string key, address indexed by);
    event SecretSet(string section, string key, address indexed by);
    event InviteCreated(bytes32 indexed codeHash, string section, uint8 role, address indexed by);
    event InviteRedeemed(bytes32 indexed codeHash, string section, address indexed redeemer);

    // ── stewardship (defined by the concrete contract) ─────────────────────
    /**
     * @dev Is `who` a base authority over this whole contract? Concrete contracts
     *      answer: any active rivet (IdentityContract), owner||host (DomainAgent),
     *      advertiser||agency (CampaignContract). Stewards get implicit role 4 on
     *      every section — they are the interchangeable owners.
     */
    function _isSteward(address who) internal view virtual returns (bool);

    modifier onlySteward() { require(_isSteward(msg.sender), "not a steward"); _; }

    // ── authorization queries (the blind check callers use) ────────────────

    /** Effective role of `who` on `section`: 4 for any steward, else the ACL grant (0 if none). */
    function roleOf(string memory section, address who) public view returns (uint8) {
        if (_isSteward(who)) return ROLE_OWNER;
        uint256 i = _aclIndex[section][who];
        if (i != 0) return _acl[section][i - 1].role;
        // Unlisted → the section's DEFAULT_MEMBER role (0/none if no default set,
        // preserving the old private-by-default behavior). This is the single
        // source the relay/plugins already read; nothing re-derives access.
        uint256 d = _aclIndex[section][DEFAULT_MEMBER];
        return d == 0 ? ROLE_NONE : _acl[section][d - 1].role;
    }

    /** True if `who` holds at least `minRole` on `section` (minRole must be > 0). */
    function authorized(string memory section, address who, uint8 minRole) public view returns (bool) {
        return minRole != ROLE_NONE && roleOf(section, who) >= minRole;
    }

    /** True if `who` is on the section at all (any role) — the cheap membership test. */
    function isMember(string memory section, address who) external view returns (bool) {
        return roleOf(section, who) != ROLE_NONE;
    }

    /** Who may change a section's membership/attributes: a steward, or a section admin. */
    function _canManage(string memory section, address who) internal view returns (bool) {
        return roleOf(section, who) >= ROLE_ADMIN;
    }

    // ── ACL management ─────────────────────────────────────────────────────

    /** Add or update a member's role on a section. Caller must manage the section. */
    function setMember(string memory section, address addr, string memory name, uint8 role, string memory meta) external {
        require(role <= ROLE_OWNER, "invalid role");
        require(role != ROLE_NONE, "use removeMember");
        require(addr != address(0), "zero address");
        require(_canManage(section, msg.sender), "not authorized to manage section");
        _trackSection(section);

        uint256 idx = _aclIndex[section][addr];
        if (idx == 0) {
            _acl[section].push(ACLEntry({ addr: addr, name: name, role: role, meta: meta }));
            _aclIndex[section][addr] = _acl[section].length; // index+1
            _memberships[addr].push(Membership({ section: section, role: role }));
        } else {
            _acl[section][idx - 1].role = role;
            _acl[section][idx - 1].name = name;
            _acl[section][idx - 1].meta = meta;
            _updateMembershipRole(addr, section, role);
        }
        emit MemberSet(section, addr, role, msg.sender);
    }

    /** Remove a member from a section. Caller must manage the section. */
    function removeMember(string memory section, address addr) external {
        require(_canManage(section, msg.sender), "not authorized to manage section");
        uint256 idx = _aclIndex[section][addr];
        require(idx != 0, "not a member");

        ACLEntry[] storage a = _acl[section];
        uint256 last = a.length - 1;
        if (idx - 1 != last) {
            a[idx - 1] = a[last];
            _aclIndex[section][a[idx - 1].addr] = idx; // moved entry keeps index+1
        }
        a.pop();
        _aclIndex[section][addr] = 0;
        _removeMembership(addr, section);
        emit MemberRemoved(section, addr, msg.sender);
    }

    // ── attributes ─────────────────────────────────────────────────────────

    /** Set a world-readable attribute on a section. Caller must manage the section. */
    function setPublic(string memory section, string memory key, string memory value) external {
        require(_canManage(section, msg.sender), "not authorized to manage section");
        _setPublic(section, key, value);
    }

    /** Internal writer — lets a concrete contract seed public attributes from its
     *  constructor (before any external call can be made), without duplicating the
     *  section/key bookkeeping. External callers go through setPublic's ACL gate. */
    function _setPublic(string memory section, string memory key, string memory value) internal {
        _trackSection(section);
        if (!_publicKeySeen[section][key]) { _publicKeySeen[section][key] = true; _publicKeyList[section].push(key); }
        _public[section][key] = value;
        emit PublicSet(section, key, msg.sender);
    }

    /** Read a public attribute — open to anyone. */
    function getPublic(string memory section, string memory key) external view returns (string memory) {
        return _public[section][key];
    }

    /** Internal read, for concrete contracts exposing their own public attrs. */
    function _getPublic(string memory section, string memory key) internal view returns (string memory) {
        return _public[section][key];
    }

    /** Set a secret attribute on a section. Caller must manage the section. */
    function setSecret(string memory section, string memory key, bytes memory value) external {
        require(_canManage(section, msg.sender), "not authorized to manage section");
        _trackSection(section);
        if (!_secretKeySeen[section][key]) { _secretKeySeen[section][key] = true; _secretKeyList[section].push(key); }
        _secret[section][key] = value;
        emit SecretSet(section, key, msg.sender);
    }

    /** Read a secret attribute — caller must hold read+ on the section. */
    function getSecret(string memory section, string memory key) external view returns (bytes memory) {
        require(authorized(section, msg.sender, ROLE_READ), "not authorized");
        return _secret[section][key];
    }

    // ── invites ────────────────────────────────────────────────────────────

    /** Issue an invite to join a section at `role`. `codeHash` = keccak256 of an off-chain code. */
    function createInvite(bytes32 codeHash, string memory section, uint8 role) external {
        require(role != ROLE_NONE && role <= ROLE_OWNER, "invalid role");
        require(_canManage(section, msg.sender), "not authorized to manage section");
        require(_invites[codeHash].issuer == address(0), "invite exists");
        _trackSection(section);
        _invites[codeHash] = Invite({ section: section, role: role, issuer: msg.sender, used: false });
        emit InviteCreated(codeHash, section, role, msg.sender);
    }

    /** Redeem an invite, adding `redeemer` to its section. Anyone holding the code can redeem. */
    function redeemInvite(bytes32 codeHash, address redeemer, string memory name) external {
        Invite storage inv = _invites[codeHash];
        require(inv.issuer != address(0) && !inv.used, "invalid invite");
        require(redeemer != address(0), "zero address");
        inv.used = true;

        if (_aclIndex[inv.section][redeemer] == 0) {
            _acl[inv.section].push(ACLEntry({ addr: redeemer, name: name, role: inv.role, meta: '{"via":"invite"}' }));
            _aclIndex[inv.section][redeemer] = _acl[inv.section].length;
            _memberships[redeemer].push(Membership({ section: inv.section, role: inv.role }));
        } else {
            _acl[inv.section][_aclIndex[inv.section][redeemer] - 1].role = inv.role;
            _updateMembershipRole(redeemer, inv.section, inv.role);
        }
        emit InviteRedeemed(codeHash, inv.section, redeemer);
    }

    // ── enumeration / getters ──────────────────────────────────────────────

    function getSectionNames() external view returns (string[] memory) { return _sectionNames; }
    function getACL(string memory section) external view returns (ACLEntry[] memory) { return _acl[section]; }
    function getSectionsForMember(address who) external view returns (Membership[] memory) { return _memberships[who]; }
    function getPublicKeys(string memory section) external view returns (string[] memory) { return _publicKeyList[section]; }
    function getSecretKeys(string memory section) external view returns (string[] memory) { return _secretKeyList[section]; }

    // ── internals ──────────────────────────────────────────────────────────

    function _trackSection(string memory section) private {
        if (!_sectionSeen[section]) { _sectionSeen[section] = true; _sectionNames.push(section); }
    }

    function _updateMembershipRole(address addr, string memory section, uint8 role) private {
        Membership[] storage m = _memberships[addr];
        for (uint256 i; i < m.length; i++) {
            if (keccak256(bytes(m[i].section)) == keccak256(bytes(section))) { m[i].role = role; return; }
        }
    }

    function _removeMembership(address addr, string memory section) private {
        Membership[] storage m = _memberships[addr];
        for (uint256 i; i < m.length; i++) {
            if (keccak256(bytes(m[i].section)) == keccak256(bytes(section))) {
                m[i] = m[m.length - 1];
                m.pop();
                return;
            }
        }
    }
}

contracts/IdentityContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./EpisteryAccess.sol";

/**
 * @title IdentityContract — a collection of devices that IS an identity
 *
 * A multisig smart wallet whose signers (rivets) are interchangeable owners: any
 * active rivet can act, add/remove rivets, sign as the identity (ERC-1271), and
 * manage the identity's sections. Add a device, lose a device and remove it with
 * another — no seed phrase, no single owner.
 *
 * Access + data for everything the identity owns (sessions, plugin data) uses the
 * common {EpisteryAccess} section mechanism: a session is a section; collaborators
 * are ACL entries on it; a plugin's config/keys are the section's attributes. The
 * rivets are the stewards — implicit role 4 on every section.
 *
 * The **host** is one signer flagged as the default backup/recovery key (e.g.
 * epistery-host). It is a rivet like any other, with no special power, and is fully
 * revocable: `removeRivet(host)` makes the identity 100% self-sovereign. It exists
 * only so a user who still controls a device can be helped to recover — never so a
 * server can broker access.
 *
 * If every server we run vanished, any one rivet + this contract + Storj is enough
 * to read and write all of the identity's data and its collaborators' shared data.
 */
interface IERC1271 {
    function isValidSignature(bytes32 hash, bytes memory signature) external view returns (bytes4 magicValue);
}

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract IdentityContract is EpisteryAccess, IERC1271 {

    bytes4 constant internal EIP1271_MAGIC_VALUE = 0x1626ba7e;
    bytes4 constant internal EIP1271_INVALID = 0xffffffff;

    // ── identity (interchangeable owners = rivets) ─────────────────────────
    address public immutable creator;          // first rivet, for provenance only
    address public host;                        // default recovery signer (a rivet), revocable
    address[] private authorizedRivets;
    mapping(address => bool) public isAuthorized;
    mapping(address => bool) public rivetActive;
    mapping(address => string) public rivetNames;
    mapping(address => uint256) public rivetAddedAt;
    mapping(address => string) public rivetPublicKeys;  // per-device key (communications fabric)
    uint256 public rivetCount;

    uint256 public removeRivetThreshold = 1;    // N-of-M to remove a rivet (governance knob)
    uint256 public messageCount;

    // Reserved section holding the identity's own world-readable profile. The
    // display name lives here as a public attribute ("name") — the on-chain home
    // that replaces the old chat.name KeyVault entry. Anyone can read it; only a
    // steward (rivet) can change it, via setPublic.
    string public constant PROFILE_SECTION = "_profile";

    // ── events ─────────────────────────────────────────────────────────────
    event IdentityCreated(address indexed creator, address indexed host, uint256 timestamp);
    event RivetAdded(address indexed rivet, address indexed addedBy, string name, uint256 timestamp);
    event RivetRemoved(address indexed rivet, address indexed removedBy, uint256 timestamp);
    event HostChanged(address indexed previousHost, address indexed newHost, address indexed by);
    event PublicKeyRegistered(address indexed rivet, string publicKey, uint256 timestamp);
    event TransactionExecuted(address indexed target, uint256 value, address indexed sender, uint256 timestamp);
    event ETHSent(address indexed recipient, uint256 amount, address indexed sender);
    event TokenSent(address indexed token, address indexed recipient, uint256 amount, address indexed sender);
    event RemoveRivetThresholdChanged(uint256 oldThreshold, uint256 newThreshold);
    event MessageReceived(address indexed from, bytes data, uint256 value, uint256 indexed messageIndex, uint256 timestamp);

    /**
     * @param firstRivet the identity's first device (the owner). Not msg.sender, so a
     *        deployer can create it on the user's behalf.
     * @param host_ optional default recovery signer (e.g. epistery-host); pass address(0) for none.
     * @param firstRivetName human name for the first device.
     * @param firstRivetPubKey the device's communications public key (empty for none) —
     *        stored in rivetPublicKeys[firstRivet] so peers can encrypt to it immediately.
     * @param displayName the identity's world-readable display name (empty for none) —
     *        seeded as the "name" public attribute of PROFILE_SECTION.
     *
     * Folding name + pubkey into the constructor makes a mint a single deploy tx:
     * no follow-up setPublic/setPublicKey round-trips.
     */
    constructor(
        address firstRivet,
        address host_,
        string memory firstRivetName,
        string memory firstRivetPubKey,
        string memory displayName
    ) {
        require(firstRivet != address(0), "first rivet required");
        creator = firstRivet;
        _addRivet(firstRivet, bytes(firstRivetName).length > 0 ? firstRivetName : "creator");
        if (bytes(firstRivetPubKey).length > 0) rivetPublicKeys[firstRivet] = firstRivetPubKey;

        if (host_ != address(0) && host_ != firstRivet) {
            _addRivet(host_, "host");
            host = host_;
        }
        if (bytes(displayName).length > 0) _setPublic(PROFILE_SECTION, "name", displayName);
        emit IdentityCreated(firstRivet, host, block.timestamp);
    }

    /** The identity's world-readable display name (PROFILE_SECTION → "name"). */
    function profileName() external view returns (string memory) {
        return _getPublic(PROFILE_SECTION, "name");
    }

    // ── stewardship: the identity itself, and any active rivet, are owners ──
    // `who == address(this)` is load-bearing: the app authorizes callers by
    // their canonical identityAddress, which for an adopted user IS this
    // contract's address (not the raw rivet EOA). So the owner accessing a
    // section on their own IdentityContract arrives as address(this) and must
    // read the top role. Active rivets are stewards too (device-level signing
    // before/without adoption, and cross-contract ERC-1271 proofs).
    function _isSteward(address who) internal view override returns (bool) {
        return who == address(this) || (isAuthorized[who] && rivetActive[who]);
    }

    modifier onlyRivet() {
        require(_isSteward(msg.sender), "caller is not an active rivet");
        _;
    }

    // ── rivet management ────────────────────────────────────────────────────

    function addRivet(address rivet, string memory name) external onlyRivet {
        require(rivet != address(0), "invalid rivet");
        require(!isAuthorized[rivet], "rivet already added");
        require(bytes(name).length > 0, "name required");
        _addRivet(rivet, name);
        emit RivetAdded(rivet, msg.sender, name, block.timestamp);
    }

    function removeRivet(address rivet) external onlyRivet {
        require(isAuthorized[rivet], "rivet not found");
        require(rivetCount > 1, "cannot remove last rivet");
        // (removeRivetThreshold is the intended N-of-M knob; enforcement lands with governance.)

        isAuthorized[rivet] = false;
        rivetActive[rivet] = false;
        rivetCount--;
        delete rivetPublicKeys[rivet];

        // Removing the host is exactly "kick out the host" → self-sovereign.
        if (rivet == host) { emit HostChanged(host, address(0), msg.sender); host = address(0); }

        emit RivetRemoved(rivet, msg.sender, block.timestamp);
    }

    /** Flag an existing rivet as the default recovery host (or clear with address(0)). */
    function designateHost(address newHost) external onlyRivet {
        require(newHost == address(0) || _isSteward(newHost), "host must be an active rivet");
        emit HostChanged(host, newHost, msg.sender);
        host = newHost;
    }

    function setRemoveRivetThreshold(uint256 newThreshold) external onlyRivet {
        require(newThreshold > 0 && newThreshold <= rivetCount, "invalid threshold");
        emit RemoveRivetThresholdChanged(removeRivetThreshold, newThreshold);
        removeRivetThreshold = newThreshold;
    }

    function _addRivet(address rivet, string memory name) private {
        authorizedRivets.push(rivet);
        isAuthorized[rivet] = true;
        rivetActive[rivet] = true;
        rivetNames[rivet] = name;
        rivetAddedAt[rivet] = block.timestamp;
        rivetCount++;
    }

    // ── per-device public key (communications fabric) ──────────────────────

    function setPublicKey(string memory publicKey) external onlyRivet {
        rivetPublicKeys[msg.sender] = publicKey;
        emit PublicKeyRegistered(msg.sender, publicKey, block.timestamp);
    }

    function getRivets() external view returns (address[] memory) {
        address[] memory active = new address[](rivetCount);
        uint256 n;
        for (uint256 i; i < authorizedRivets.length; i++) {
            address r = authorizedRivets[i];
            if (isAuthorized[r] && rivetActive[r]) { active[n++] = r; }
        }
        return active;
    }

    function isRivet(address rivet) external view returns (bool) {
        return isAuthorized[rivet] && rivetActive[rivet];
    }

    // ── act as the identity ─────────────────────────────────────────────────

    function executeTransaction(address target, uint256 value, bytes memory data)
        external payable onlyRivet returns (bool success, bytes memory returnData)
    {
        require(target != address(0), "invalid target");
        require(address(this).balance >= value, "insufficient balance");
        (success, returnData) = target.call{value: value}(data);
        require(success, "transaction failed");
        emit TransactionExecuted(target, value, msg.sender, block.timestamp);
    }

    function sendETH(address payable recipient, uint256 amount) external onlyRivet {
        require(recipient != address(0), "zero recipient");
        require(address(this).balance >= amount, "insufficient balance");
        recipient.transfer(amount);
        emit ETHSent(recipient, amount, msg.sender);
    }

    function sendToken(address token, address recipient, uint256 amount) external onlyRivet {
        require(token != address(0) && recipient != address(0), "zero address");
        require(IERC20(token).transfer(recipient, amount), "token transfer failed");
        emit TokenSent(token, recipient, amount, msg.sender);
    }

    function approveToken(address token, address spender, uint256 amount) external onlyRivet {
        require(token != address(0) && spender != address(0), "zero address");
        require(IERC20(token).approve(spender, amount), "token approval failed");
    }

    function getBalance() external view returns (uint256) { return address(this).balance; }

    // ── ERC-1271: the identity signs when any active rivet signed ──────────

    function isValidSignature(bytes32 hash, bytes memory signature) external view override returns (bytes4) {
        require(signature.length == 65, "invalid signature length");
        bytes32 r; bytes32 s; uint8 v;
        assembly {
            r := mload(add(signature, 32))
            s := mload(add(signature, 64))
            v := byte(0, mload(add(signature, 96)))
        }
        if (v < 27) v += 27;
        bytes32 ethHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash));
        address signer = ecrecover(ethHash, v, r, s);
        return (isAuthorized[signer] && rivetActive[signer]) ? EIP1271_MAGIC_VALUE : EIP1271_INVALID;
    }

    // ── receive value / accept messages ────────────────────────────────────

    receive() external payable {}

    fallback() external payable {
        messageCount++;
        emit MessageReceived(msg.sender, msg.data, msg.value, messageCount, block.timestamp);
    }
}

